import XCTest

final class PromenadaUITests: XCTestCase {
    private let fixture = ""
    override func setUpWithError() throws { continueAfterFailure = false }
    func testRememberedAccessOfflineAndLogout() {
        let app = XCUIApplication()
        app.launchEnvironment["PROMENADA_TEST_REPORT"] = fixture
        app.launchArguments = ["--reset-test-access"]
        app.launch()
        let input = app.secureTextFields["journal-password"]
        XCTAssertTrue(input.waitForExistence(timeout: 20))
        input.tap(); input.typeText("wrong-password")
        app.buttons["journal-unlock"].tap()
        XCTAssertTrue(app.staticTexts["journal-error"].waitForExistence(timeout: 10))
        XCTAssertTrue(app.staticTexts["journal-error"].label.contains("hasło"))
        input.tap(); input.typeText("test-only-password")
        app.buttons["journal-unlock"].tap()
        let plan = app.webViews.buttons["Plan lekcji"]
        XCTAssertTrue(plan.waitForExistence(timeout: 25), app.debugDescription)
        XCTAssertFalse(input.exists)
        plan.tap()
        XCTAssertTrue(app.webViews.staticTexts["Cały tydzień"].waitForExistence(timeout: 5))
        let screenshot = XCTAttachment(screenshot: app.screenshot())
        screenshot.name = "Plan lekcji – iPhone"; screenshot.lifetime = .keepAlways; add(screenshot)
        app.webViews.buttons["Wczytaj raport"].tap()
        XCTAssertTrue(app.webViews.staticTexts["Masz najnowszy opublikowany raport."].waitForExistence(timeout: 10))
        app.webViews.buttons["Więcej działów"].tap()
        XCTAssertTrue(app.webViews.buttons.matching(NSPredicate(format: "label CONTAINS %@", "Frekwencja")).firstMatch.exists)
        app.webViews.buttons["Wiadomości"].tap()
        let firstMessage = app.webViews.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "Piątkowa wyprawa do planetarium")).firstMatch
        XCTAssertTrue(firstMessage.waitForExistence(timeout: 5), app.debugDescription)
        firstMessage.tap()
        let mark = app.webViews.buttons["Oznacz jako przeczytane"].firstMatch
        XCTAssertTrue(mark.waitForExistence(timeout: 5))
        mark.tap()
        app.terminate()
        app.launchArguments = []
        app.launchEnvironment["PROMENADA_TEST_OFFLINE"] = "1"
        app.launch()
        XCTAssertTrue(app.webViews.buttons["Plan lekcji"].waitForExistence(timeout: 25), app.debugDescription)
        XCTAssertFalse(app.secureTextFields["journal-password"].exists)
        XCTAssertTrue(app.webViews.staticTexts["Bez połączenia z serwerem. Pokazuję ostatni zapisany raport."].exists)
        app.webViews.buttons["Wiadomości"].tap()
        app.webViews.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "Piątkowa wyprawa do planetarium")).firstMatch.tap()
        XCTAssertTrue(app.webViews.buttons["Przeczytane"].firstMatch.waitForExistence(timeout: 5))
        let offline = XCTAttachment(screenshot: app.screenshot())
        offline.name = "Poczta – zapamiętany dostęp offline"; offline.lifetime = .keepAlways; add(offline)
        app.webViews.buttons["Wyloguj"].tap()
        app.alerts.buttons["Wyloguj"].tap()
        XCTAssertTrue(app.secureTextFields["journal-password"].waitForExistence(timeout: 5))
        app.terminate(); app.launch()
        XCTAssertTrue(app.secureTextFields["journal-password"].waitForExistence(timeout: 15))
    }

    func testSectionsAndAttachment() {
        let app = XCUIApplication()
        app.launchEnvironment["PROMENADA_TEST_REPORT"] = fixture
        app.launchArguments = ["--reset-test-access"]
        app.launch()
        let input=app.secureTextFields["journal-password"]
        XCTAssertTrue(input.waitForExistence(timeout:20))
        let gate = XCTAttachment(screenshot:app.screenshot());gate.name="Mahbrus – pierwszy dostęp";gate.lifetime = .keepAlways;add(gate)
        input.tap();input.typeText("test-only-password");app.buttons["journal-unlock"].tap()
        XCTAssertTrue(app.webViews.buttons["Plan lekcji"].waitForExistence(timeout:25))
        let overview=XCTAttachment(screenshot:app.screenshot());overview.name="Mahbrus – sprawy";overview.lifetime = .keepAlways;add(overview)
        app.webViews.buttons["Oceny"].tap()
        XCTAssertTrue(app.webViews.staticTexts["Matematyka"].firstMatch.waitForExistence(timeout:5))
        for name in ["Ogłoszenia","Terminy","Frekwencja","Uwagi","Zadania","Osiągnięcia"] {
            app.webViews.buttons["Więcej działów"].tap()
            let row=app.webViews.buttons.matching(NSPredicate(format:"label BEGINSWITH %@",name)).firstMatch
            XCTAssertTrue(row.waitForExistence(timeout:5)); if !row.isHittable { app.webViews.firstMatch.swipeUp() }; row.tap()
            XCTAssertTrue(app.webViews.staticTexts[name].firstMatch.waitForExistence(timeout:5),name)
        }
        app.webViews.buttons["Wiadomości"].tap()
        app.webViews.buttons.matching(NSPredicate(format:"label CONTAINS %@","Piątkowa wyprawa do planetarium")).firstMatch.tap()
        let download=app.webViews.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","Otwórz · zgoda-demo.txt")).firstMatch
        XCTAssertTrue(download.waitForExistence(timeout:5)); if !download.isHittable { app.webViews.firstMatch.swipeUp() }; download.tap()
        XCTAssertTrue(app.otherElements["ActivityListView"].waitForExistence(timeout:5),app.debugDescription)
        let sharing=XCTAttachment(screenshot:app.screenshot());sharing.name="Mahbrus – załącznik";sharing.lifetime = .keepAlways;add(sharing)
        XCTAssertEqual(app.otherElements["LP.CaptionBar.TopCaption"].label,"zgoda-demo")
        app.buttons["header.closeButton"].tap()
        XCTAssertTrue(download.waitForExistence(timeout:5)); if !download.isHittable { app.webViews.firstMatch.swipeUp() }; download.tap()
        XCTAssertTrue(app.otherElements["ActivityListView"].waitForExistence(timeout:5))
        app.buttons["header.closeButton"].tap()
    }

    func testTabletLayout() {
        let app=XCUIApplication()
        app.launchEnvironment["PROMENADA_TEST_REPORT"]=fixture
        app.launchArguments=["--reset-test-access"]
        app.launch()
        let input=app.secureTextFields["journal-password"]
        XCTAssertTrue(input.waitForExistence(timeout:20))
        input.tap();input.typeText("test-only-password");app.buttons["journal-unlock"].tap()
        XCTAssertTrue(app.webViews.buttons["Plan lekcji"].waitForExistence(timeout:25))
        app.webViews.buttons["Plan lekcji"].tap()
        XCTAssertTrue(app.webViews.staticTexts["Cały tydzień"].waitForExistence(timeout:5))
        let shot=XCTAttachment(screenshot:app.screenshot());shot.name="Mahbrus – plan na iPadzie";shot.lifetime = .keepAlways;add(shot)
        app.webViews.buttons["Frekwencja"].tap()
        XCTAssertTrue(app.webViews.staticTexts["Frekwencja"].firstMatch.waitForExistence(timeout:5))
    }

    func testStudentLoginRemembersOnlyStudentAccess() {
        let app = XCUIApplication()
        app.launchArguments = ["--reset-test-access"]
        app.launchEnvironment["PROMENADA_TEST_REPORT"] = ""
        app.launch()
        XCTAssertTrue(app.secureTextFields["journal-password"].waitForExistence(timeout: 20))
        app.segmentedControls.buttons["Uczeń"].tap()
        app.textFields["journal-login"].tap(); app.textFields["journal-login"].typeText("student-demo")
        app.secureTextFields["journal-password"].tap(); app.secureTextFields["journal-password"].typeText("student-test-password")
        app.buttons["journal-unlock"].tap()
        XCTAssertTrue(app.webViews.buttons["Plan lekcji"].waitForExistence(timeout: 25), app.debugDescription)
        XCTAssertFalse(app.webViews.buttons["Oboje"].exists)
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Mahbrus – konto ucznia"; shot.lifetime = .keepAlways; add(shot)
        app.terminate(); app.launchArguments = []; app.launchEnvironment["PROMENADA_TEST_OFFLINE"] = "1"; app.launch()
        XCTAssertTrue(app.webViews.buttons["Plan lekcji"].waitForExistence(timeout: 25))
        XCTAssertFalse(app.secureTextFields["journal-password"].exists)
        XCTAssertFalse(app.webViews.buttons["Oboje"].exists)
        app.webViews.buttons["Wyloguj"].tap(); app.alerts.buttons["Wyloguj"].tap()
        XCTAssertTrue(app.secureTextFields["journal-password"].waitForExistence(timeout: 10))
    }
    func testStudentRejectsFamilyReportEvenWithItsPassword() {
        let app = XCUIApplication()
        app.launchArguments = ["--reset-test-access"]
        app.launchEnvironment["PROMENADA_TEST_REPORT"] = fixture
        app.launch()
        XCTAssertTrue(app.secureTextFields["journal-password"].waitForExistence(timeout: 20))
        app.segmentedControls.buttons["Uczeń"].tap()
        app.textFields["journal-login"].tap(); app.textFields["journal-login"].typeText("student-demo")
        app.secureTextFields["journal-password"].tap(); app.secureTextFields["journal-password"].typeText("test-only-password")
        app.buttons["journal-unlock"].tap()
        XCTAssertTrue(app.staticTexts["journal-error"].waitForExistence(timeout: 15))
        XCTAssertFalse(app.webViews.buttons["Plan lekcji"].exists)
    }
}
